function getTextConfig({ element }) {
    return {
        defaultTab: "text",
        tabs: [
            buildTextTab({
                element
            }),
            buildTransformTab({
                element
            }),
            buildBlendingTab({
                element
            })
        ]
    };
}
function getVideoConfig({ element, mediaAsset }) {
    const showAudioTab = mediaAsset?.hasAudio !== false;
    return {
        defaultTab: "transform",
        tabs: [
            buildTransformTab({
                element
            }),
            ...showAudioTab ? [
                buildAudioTab({
                    element
                })
            ] : [],
            buildSpeedTab({
                element
            }),
            buildBlendingTab({
                element
            }),
            buildMasksTab({
                element
            }),
            buildClipEffectsTab({
                element
            })
        ]
    };
}
